/* --- 天空是树的海   感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. -- */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Dancing+Script:wght@400;700&display=swap'); /* 英文手写体 */
@import url("https://fontsapi.zeoseven.com/438/main/result.css"); /* 全局中文: Huiwen-ZhengKai */
@import url("https://fontsapi.zeoseven.com/116/main/result.css"); /* 代码: Kingnammm Maiyuan 2 */
@import url("https://fontsapi.zeoseven.com/508/main/result.css"); /* 引用: pingfangqignchunti */
@import url("https://fontsapi.zeoseven.com/703/main/result.css"); /* 标题: Maruko Gothic CJKsc */

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #F8FFF6; /* 极浅的绿意背景 */
    --panel-bg-color: rgba(255, 255, 255, 0.75);
    --panel-bg-hover: rgba(255, 255, 255, 0.9);
    --card-bg: rgba(245, 252, 248, 0.85);
    --input-bg: rgba(255, 255, 255, 0.8);
    --text-main: #28503C; /* 森林深绿色文字 */
    --text-subtle: #7A9988; /* 柔和的灰绿色文字 */
    --border-color: rgba(130, 180, 150, 0.4);
    --accent-color: #6BC395; /* 主题绿 */
    --selected-color: #4A9A70; /* 选中状态的深绿色 */
    --font-english: 'Dancing Script', cursive;
    --font-main: "Huiwen-ZhengKai", var(--font-english);
    --font-quote: "pingfangqignchunti", var(--font-english);
    --font-code: "Kingnammm Maiyuan 2", monospace;
    --font-title: "Maruko Gothic CJKsc", var(--font-english);
    --border-radius: 6px;
}

/* --- 3. 全局样式 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg) !important; 
    background-image: url('https://images.unsplash.com/photo-1448375240586-882707db888b?q=80&w=2070&auto=format&fit=crop');
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--text-main); font-weight: normal; }

/* --- 4. 顶部导航栏 & 挂件 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); border: none; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.3s ease; filter: grayscale(50%) brightness(1.2); }
.drawer-icon.fa-fw:hover { transform: scale(1.1); filter: grayscale(0%) brightness(1); }

/* 自定义导航栏图标 */
.drawer-icon.fa-sliders, #ai-config-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/Qs06/1094X1384/2026-03-20_151342.png/webp');}
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/U1ey/1305X1574/2026-03-20_151402.png/webp');}
.drawer-icon.fa-font, #advanced-formatting-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/Qs06/1094X1384/2026-03-20_151342.png/webp');}
.drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/U1ey/1305X1574/2026-03-20_151402.png/webp');}
.drawer-icon.fa-user, #user-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/Qs06/1094X1384/2026-03-20_151342.png/webp');}
.drawer-icon.fa-image, .drawer-icon.fa-panorama { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/U1ey/1305X1574/2026-03-20_151402.png/webp');}
.drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/Qs06/1094X1384/2026-03-20_151342.png/webp');}
.drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/U1ey/1305X1574/2026-03-20_151402.png/webp');}
.drawer-icon.fa-face-smile, #persona-management-button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/Qs06/1094X1384/2026-03-20_151342.png/webp');}
.drawer-icon.fa-address-card, #character_popup_button .drawer-icon { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/U1ey/1305X1574/2026-03-20_151402.png/webp');}

.drawer-content { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/S6bR/1200X800/670f83aee15517c90d769ca93ac5dd44.jpg/webp'); background-size: cover; background-position: center; border: none !important; border-radius: var(--border-radius); }

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 15px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { pointer-events: auto; width: 90% !important; max-width: 800px !important; margin: 0 auto !important; border-radius: 25px !important; background-color: var(--input-bg) !important; padding: 10px 15px !important; backdrop-filter: blur(10px) !important; -webkit-backdrop-filter: blur(10px) !important; transition: all 0.5s ease !important; position: relative; border: 1px solid rgba(0, 0, 0, 0.05) !important; border-style: solid !important; }
#send_form:hover { transform: translateY(-5px) !important; background-color: var(--panel-bg-hover) !important; }
#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '在树叶的缝隙间，今天有什么悄悄话？'; 
    color: #AAAAAA; 
    position: absolute; 
    top: 50%; left: 50%; 
    transform: translate(-50%, -50%); 
    font-family: var(--font-quote); 
    font-size: 0.5em; 
    pointer-events: none; 
    z-index: 10; 
    white-space: nowrap; 
    letter-spacing: 2px; 
}
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 32px; height: 32px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; filter: grayscale(60%); }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.1); filter: grayscale(0%); }
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/2Cap/1829X1041/2026-03-20_151651.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/U1ey/1305X1574/2026-03-20_151402.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/Qs06/1094X1384/2026-03-20_151342.png/webp'); }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/x3qr/1107X1519/2026-02-26_112246.png/webp'); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/7DIP/1467X1509/2026-02-26_112312.png/webp'); }

/* --- 6. 核心：消息卡片布局与样式 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 6px !important; 
    margin: 45px auto 40px !important; 
    width: 85%; max-width: 700px; 
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border: 1px solid rgba(255, 255, 255, 0.5) !important; 
    border-style: solid !important; 
    border-radius: 6px !important; 
    overflow: visible !important; 
    position: relative; 
}

.mes[is_user="true"] { background: rgba(245, 255, 250, 0.85) !important; }
.mes[is_user="false"] { background: rgba(230, 250, 240, 0.9) !important; }

/* --- 新增：消息框边框星星装饰 --- */
@keyframes star-twinkle {
    0% { opacity: 0.4; transform: scale(0.8) rotate(0deg); text-shadow: 0 0 2px rgba(107, 195, 149, 0.2); }
    50% { opacity: 1; transform: scale(1.1) rotate(10deg); text-shadow: 0 0 8px rgba(107, 195, 149, 0.6); }
    100% { opacity: 0.4; transform: scale(0.8) rotate(0deg); text-shadow: 0 0 2px rgba(107, 195, 149, 0.2); }
}

.mes::before, .mes::after {
    position: absolute;
    font-family: sans-serif;
    z-index: 20;
    pointer-events: none;
    animation: star-twinkle 4s infinite ease-in-out;
}

/* AI 消息框星星装饰 (左上，右下) */
.mes[is_user="false"]::before {
    content: '✦';
    top: -12px;
    left: -12px;
    font-size: 26px;
    color: var(--accent-color);
}
.mes[is_user="false"]::after {
    content: '✨';
    bottom: -10px;
    right: -10px;
    font-size: 20px;
    animation-delay: 1s;
}

/* User 消息框星星装饰 (右上，左下) */
.mes[is_user="true"]::before {
    content: '✦';
    top: -12px;
    right: -12px;
    font-size: 26px;
    color: #a1ffc0;
}
.mes[is_user="true"]::after {
    content: '✨';
    bottom: -10px;
    left: -10px;
    font-size: 20px;
    animation-delay: 1.5s;
}
/* -------------------------------- */

.mes .mesAvatarWrapper {
    display: flex; justify-content: center; align-items: center; padding: 0;
    width: 100%;
    background-size: cover; background-position: center;
    position: relative; z-index: 5;
    height: 180px !important; 
    min-height: 180px !important;
    overflow: visible !important;
}
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/08t7/4578X2298/2026-03-20_152230.jpg/webp'); }
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/TYyZ/4578X2298/2026-03-20_152124.jpg/webp'); }

/* 头像拍立得设计 & 左右对齐 & 新增树叶动效 */
.mes .avatar {
    position: absolute;
    top: 50%; 
    transform: translateY(-50%);
    width: 135px; height: 195px; 
    background-color: #FFFFFF !important;
    padding: 8px 8px 26px 8px !important; 
    border: 1px solid rgba(0, 0, 0, 0.1) !important;
    border-style: solid !important;
    z-index: 30; 
    display: flex !important; 
    align-items: center;
    justify-content: center;
    border-radius: 2px !important;
    box-shadow: 2px 4px 10px rgba(0,0,0,0.05) !important; 
    overflow: hidden; 
}

@keyframes gentle-rotate { 0% { transform: rotate(0deg) scale(1.5); } 100% { transform: rotate(360deg) scale(1.5); } }
@keyframes float-leaves { 0% { transform: translateY(10px) rotate(-10deg) scale(0.8); opacity: 0; } 25% { opacity: 0.7; } 75% { transform: translateY(-40px) rotate(15deg) scale(1.2); opacity: 0; } 100% { opacity: 0; } }

.mes .avatar::before { 
    content: ''; 
    position: absolute; 
    top: -25%; 
    left: -25%; 
    width: 150%; 
    height: 150%; 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/a4Nt/1403X1493/2026-03-20_144152.png/webp'); 
    background-size: contain; 
    background-repeat: no-repeat; 
    background-position: center; 
    z-index: -1; 
    animation: gentle-rotate 25s linear infinite; 
    opacity: 0.8; 
}
.mes .avatar::after { content: '🍃 ☘️'; position: absolute; bottom: 5px; left: 10px; font-size: 20px; color: rgba(107, 195, 149, 0.7); opacity: 0; animation: float-leaves 5s infinite ease-in-out; text-shadow: 0 0 5px rgba(255, 255, 255, 0.5); animation-delay: 0.5s; }
.mes[is_user="false"] .avatar { left: 8%; }
.mes[is_user="true"] .avatar { right: 8%; left: auto; }
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 0 !important; border: none !important; image-rendering: -webkit-optimize-contrast; image-rendering: crisp-edges; filter: sepia(10%); }

.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 40px 30px 40px 30px !important; margin-top: 0 !important; position: relative; border: none !important; overflow: visible !important; min-height: 100px !important; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 10px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { content: "☘️ 树叶正在悄悄传递思绪..."; font-family: var(--font-title); font-size: 14px !important; color: var(--accent-color); visibility: visible; letter-spacing: 1px; }
.mes_reasoning { border-left: 2px solid var(--accent-color) !important; padding-left: 15px !important; margin-bottom: 20px !important; color: var(--text-subtle); }
.mes .mes_text { line-height: 1.9; color: var(--text-main); font-size: 15px; }

/* --- 排版与文字特效系统 --- */
.mes_text h1 { font-family: var(--font-title); color: var(--accent-color); font-size: 1.7em; text-align: center; position: relative; padding-bottom: 15px; margin: 30px 0 20px 0; border-bottom: 1px solid var(--border-color) !important; font-weight: normal; letter-spacing: 3px; }
.mes_text h1::after { content: '🍃'; position: absolute; bottom: -13px; left: 50%; transform: translateX(-50%); color: var(--accent-color); background: var(--theme-bg); padding: 0 12px; font-size: 1.2em; }
.mes[is_user="false"] .mes_text h1::after { background: rgba(230, 250, 240, 1) !important; } 
.mes[is_user="true"] .mes_text h1::after { background: rgba(245, 255, 250, 1) !important; } 
.mes_text h2 { font-family: var(--font-title); color: var(--text-main); font-size: 1.4em; padding: 6px 0 6px 15px; border-left: 3px solid var(--accent-color) !important; margin: 25px 0 15px 0; background: linear-gradient(to right, rgba(107, 195, 149, 0.1) 0%, transparent 100%); border-radius: 0 8px 8px 0; font-weight: normal; }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: normal !important; color: var(--italics_text_color); background: rgba(107, 195, 149, 0.15); padding: 2px 6px; border-radius: 4px; margin: 0 2px; }
.mes_text strong, .mes_text b { font-family: var(--font-title); color: var(--text-main); font-weight: normal; border-bottom: 1px solid var(--accent-color) !important; padding: 0 2px; }
.mes_text blockquote { background-color: rgba(255, 255, 255, 0.5); border: none !important; border-left: 3px solid var(--accent-color) !important; padding: 12px 18px; border-radius: 0 8px 8px 0; margin: 18px 0; font-family: var(--font-quote); color: var(--quote_text_color); position: relative; }
.mes_text span.quote, .mes_text q, .mes_text .dialogue { font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text code { font-family: var(--font-code); background-color: rgba(107, 195, 149, 0.1) !important; color: var(--text-main) !important; padding: 2px 6px; border-radius: 4px; border: none !important; }

/* --- 楼层信息、时间戳与编辑按钮 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }
.mes .mes_block > .ch_name { display: flex !important; position: absolute; top: 25px !important; left: 30px !important; right: 30px !important; width: auto !important; align-items: flex-start !important; background: transparent !important; border: none !important; z-index: 100; transform: none !important; padding: 0; }
.mes[is_user="false"] .ch_name { justify-content: flex-end !important; padding-right: 15px; }
.mes[is_user="true"] .ch_name { justify-content: flex-start !important; padding-left: 15px; }
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; flex-wrap: wrap !important; }
.mes .ch_name .name_text { font-family: var(--font-english); font-size: 16px !important; color: var(--text-main) !important; }
.mes .mesIDDisplay, .mes .mes_timer { position: static !important; color: #999 !important; font-size: 12px !important; line-height: 1 !important; transform: none !important; }
.mes .mesIDDisplay { font-family: var(--font-title); }

/* 悬浮侧边工具栏 */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; position: static !important; opacity: 0.5; transition: opacity 0.3s ease; pointer-events: auto !important; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(255, 255, 255, 0.6) !important; backdrop-filter: blur(4px); color: #555 !important; padding: 6px !important; border-radius: 6px !important; cursor: pointer; transition: all 0.2s ease; font-size: 14px !important; height: auto !important; width: auto !important; line-height: 1 !important; border: none !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-color) !important; color: white !important; transform: scale(1.1); }

/* 打字提示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/DXMb/1728X1281/2026-03-20_151318.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; filter: grayscale(50%); animation: pulse 1.5s infinite ease-in-out; border: none !important; height: 40px !important; width: 40px !important; margin: 10px auto !important; }
#typing_indicator .dot { display: none !important; }
@keyframes pulse { 0% { transform: scale(0.95); opacity: 0.7; } 50% { transform: scale(1.05); opacity: 1; } 100% { transform: scale(0.95); opacity: 0.7; } }

/* --- 全局UI无边框设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: var(--card-bg) !important; border: none !important; border-radius: 4px !important; padding: 8px 12px !important; margin-bottom: 8px !important; color: var(--text-main) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: var(--input-bg) !important; border: 1px solid rgba(0, 0, 0, 0.08) !important; border-style: solid !important; color: var(--text-main) !important; border-radius: 4px !important; padding: 8px !important; }
input:focus, textarea:focus, select:focus { outline: 1px solid var(--accent-color) !important; }
.menu_button { background-color: var(--card-bg) !important; border: none !important; color: var(--text-main) !important; transition: all 0.2s ease; border-radius: 4px !important; }
.menu_button:hover { background-color: var(--accent-color) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-color) !important; }

/* 弹窗设计 */
dialog.popup { background-color: transparent !important; border: none !important; }
dialog.popup .popup-body, #dialogue_popup { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/S6bR/1200X800/670f83aee15517c90d769ca93ac5dd44.jpg/webp') !important; background-size: cover !important; background-position: center !important; border: none !important; border-radius: var(--border-radius) !important; position: relative; overflow: hidden; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(240, 255, 248, 0.75); backdrop-filter: blur(5px); z-index: 0; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on { background-color: var(--selected-color) !important; color: #fff !important; }
#left-nav-panel .menu_button.selected { background-color: var(--selected-color) !important; color: #fff !important; }

/* 滑块设计 */
input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none !important; appearance: none !important; width: 28px !important; height: 28px !important; background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/gjxr/1604X1607/2026-03-20_151331.png/webp') !important; filter: grayscale(50%); background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; background-color: transparent !important; border: none !important; cursor: pointer !important; }
input[type="range"]::-moz-range-thumb { width: 28px !important; height: 28px !important; background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260320/gjxr/1604X1607/2026-03-20_151331.png/webp') !important; filter: grayscale(50%); background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; background-color: transparent !important; border: none !important; cursor: pointer !important; }
.neo-range-slider { background: rgba(150, 150, 150, 0.3) !important; }

/* --- 楼层信息显示 --- */
.mes .mesIDDisplay {
    position: absolute;
    top: 195px !important; 
    background: rgba(250, 252, 254, 0.9) !important;
    border: 1px solid rgba(107, 195, 149, 0.3) !important;
    border-style: solid !important;
    color: var(--accent-color) !important; 
    font-size: 13px !important; 
    backdrop-filter: blur(4px) !important;
    z-index: 100; 
    padding: 4px 12px !important;
    white-space: nowrap;
    line-height: 1 !important;
    border-radius: 2px !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    right: auto !important; 
    font-family: var(--font-title); 
}
/* 楼层自定义文字 */
.mesIDDisplay::before { content: '天空之海 · 第 '; color: #8a9a8f; }
.mesIDDisplay::after { content: ' 片树叶'; color: #8a9a8f; }

/* --- 手机端适配 --- */
@media (max-width: 768px) {
    .mes .mesIDDisplay { font-size: 11px !important; padding: 3px 8px !important; top: 195px !important; left: 50% !important; transform: translateX(-50%) !important; }
    .mes[is_user="false"] .avatar { left: 4%; }
    .mes[is_user="true"] .avatar { right: 4%; }
}

/* =========================================================
   【修复】删除消息确认对话框按钮
   ========================================================= */
#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { display: inline-block !important; visibility: visible !important; opacity: 1 !important; pointer-events: auto !important; position: relative !important; z-index: 10001 !important; background-color: var(--card-bg) !important; color: var(--text-main) !important; border: 1px solid var(--border-color) !important; border-radius: 8px !important; padding: 10px 20px !important; margin: 10px 5px !important; cursor: pointer !important; font-family: var(--font-main) !important; font-size: 14px !important; transition: all 0.2s ease !important; }
#dialogue_del_mes_ok:hover { background-color: #d32f2f !important; color: #fff !important; transform: scale(1.05) !important; border-color: #d32f2f !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--accent-color) !important; color: #fff !important; transform: scale(1.05) !important; border-color: var(--accent-color) !important; }
#dialogue_popup > *, #dialogue_popup .popup-body > *, #dialogue_popup button, #dialogue_popup input { pointer-events: auto !important; position: relative !important; z-index: 10001 !important; }
#dialogue_popup::before { pointer-events: none !important; }
.dialogue_popup_controls, #dialogue_popup .popup-buttons { display: flex !important; justify-content: center !important; gap: 15px !important; margin-top: 20px !important; pointer-events: auto !important; z-index: 10001 !important; }
